var should=require("should"),stringify=require("../lib/querystring").build;describe("stringify",function(){describe("with null",function(){it("throws",function(){(function(){stringify(null)}).should.throw()})}),describe("with a number",function(){it("throws",function(){(function(){stringify(100)}).should.throw()})}),describe("with a string",function(){describe("that is empty",function(){it("throws",function(){(function(){stringify("")}).should.throw()})}),describe("that doesnt contain an equal sign",function(){it("throws",function(){(function(){stringify("boomshagalaga")}).should.throw()})}),describe("that contains an equal sign",function(){it("works",function(){stringify("hello=123").should.eql("hello=123")})})}),describe("with an array",function(){describe("with key val objects",function(){it("works",function(){stringify([{foo:"bar"}]).should.eql("foo=bar")})}),describe("where all elements are strings with an equal sign",function(){it("works",function(){stringify(["bar=123","quux="]).should.eql("bar=123&quux=")})}),describe("with random words",function(){it("throws",function(){(function(){stringify(["hello","there"])}).should.throw()})}),describe("with integers",function(){it("throws",function(){(function(){stringify([123,432])}).should.throw()})})}),describe("with an object",function(){it("works",function(){stringify({test:100}).should.eql("test=100")}),describe("with object where val is an array",function(){it("works",function(){stringify({foo:["bar","baz"]}).should.eql("foo[]=bar&foo[]=baz")})}),describe("with object where val is an array of key val objects",function(){it("works",function(){stringify({foo:[{1:"bar"},{2:"baz"}]}).should.eql("foo[][1]=bar&foo[][2]=baz")})})})});